import { IBeginRequest, IContinueRequest, IResumeRequest, ReqResServer } from '@game-studio/server-comms';

import { IBaseServerResponse } from '../types';
import { IContinueQueueItem } from './continue-queue';
import { inversifyContainer } from '../inversify/container';
import { environment } from '../services/environment';
import { gameConfig } from '../models/config-model';

export abstract class AbstractGameServer extends ReqResServer<IBaseServerResponse> {
    protected preventPurchaseAttempts = false;
    protected realityCheckDuration: number = 3600; // 3600 seconds = 60 minutes

    public get canPurchase() : boolean {
        return !this.preventPurchaseAttempts;
    }

    public abstract resumeRequest<T extends IBaseServerResponse = IBaseServerResponse>(skinName: string): Promise<T>;
    public abstract beginRequest<T extends IBaseServerResponse = IBaseServerResponse>(skinName: string, freePlay: boolean): Promise<T>;
    public abstract continueRequest<T extends IBaseServerResponse = IBaseServerResponse>(additionalData: unknown): Promise<T>;
    public abstract queueContinueRequest(item: IContinueQueueItem): void;

    protected resume<TBody extends IResumeRequest, TResponse extends IBaseServerResponse>(body: TBody): Promise<TResponse> {
        if (gameConfig.engineName === 'unset') {
            throw new Error('EngineName has not been set. Either set it in the initial IEngineConfig or call gameConfig.setEngineName() after initialisation');
        }

        const endpoints = inversifyContainer.endPoints;
        const url: string = endpoints.urls[environment].game;
        return this.makeRequest(`${url}${endpoints.RESUME}`, body);
    }

    protected begin<TBody extends IBeginRequest, TResponse extends IBaseServerResponse>(body: TBody): Promise<TResponse> {
        const endpoints = inversifyContainer.endPoints;
        const url: string = endpoints.urls[environment].game;
        return this.makeRequest(`${url}${endpoints.BEGIN}`, body);
    }

    protected continue<TBody extends IContinueRequest, TResponse extends IBaseServerResponse>(body: TBody): Promise<TResponse> {
        const endpoints = inversifyContainer.endPoints;
        const url: string = endpoints.urls[environment].game;
        if (endpoints.CONTINUE === undefined) {
            throw new Error('Attempted to make a continue request with no continue url set in endpoints.');
        }

        return this.makeRequest(`${url}${endpoints.CONTINUE}`, body);
    }
}
